#[test]
fn randr_rebuild_preserves_primary_while_output_resource_exists() {
    let mut state = ServerState::new();
    let output = state.randr.outputs[0].output_id;

    // An untouched topology-derived primary is not sticky. Leave the
    // freshly rebuilt fallback in place when no client selected it.
    state.randr.primary_output = 0;
    assert!(!restore_primary_output_after_rebuild(
        output,
        false,
        &mut state.randr,
    ));
    assert_eq!(state.randr.primary_output, 0);

    // Disconnection does not retire the RANDR output resource, so a
    // client-selected primary remains meaningful and must survive.
    state.randr.outputs[0].connected = false;
    state.randr.primary_output = 0;
    assert!(restore_primary_output_after_rebuild(
        output,
        true,
        &mut state.randr,
    ));
    assert_eq!(state.randr.primary_output, output);

    // An explicit None primary is likewise client-owned state.
    state.randr.primary_output = output;
    assert!(restore_primary_output_after_rebuild(
        0,
        true,
        &mut state.randr,
    ));
    assert_eq!(state.randr.primary_output, 0);

    // Once the old resource is absent, keep the freshly rebuilt state's
    // fallback instead of restoring a dangling xid.
    state.randr.primary_output = output;
    assert!(!restore_primary_output_after_rebuild(
        0x00de_ad01,
        true,
        &mut state.randr,
    ));
    assert_eq!(state.randr.primary_output, output);
}

#[test]
fn mode_timing_passes_kernel_timing_and_masks_drm_only_flags() {
    // A real 2560x1440@59.95 mode: timing must pass through verbatim,
    // and DRM-only flag bits above the RANDR RR_* range must be masked
    // so we never advertise a bit RANDR would misinterpret.
    let m = crate::platform::drm::Mode {
        name: "2560x1440".into(),
        width: 2560,
        height: 1440,
        vrefresh: 60,
        preferred: true,
        clock_khz: 241_500,
        hsync_start: 2608,
        hsync_end: 2640,
        htotal: 2720,
        vsync_start: 1443,
        vsync_end: 1448,
        vtotal: 1481,
        vscan: 1,
        // PHSYNC(0x1) | PVSYNC(0x4) kept; DBLCLK(0x1000, DRM-only) dropped.
        flags: 0x1 | 0x4 | 0x1000,
    };
    let t = mode_timing(&m).expect("real timing => Some");
    assert_eq!(t.clock_khz, 241_500);
    assert_eq!(t.htotal, 2720);
    assert_eq!(t.vtotal, 1481);
    assert_eq!(t.hsync_start, 2608);
    assert_eq!(t.vsync_end, 1448);
    assert_eq!(t.mode_flags, 0x5, "DRM-only bits masked to RR_* range");

    // Synthetic/nested mode (no clock) => None => RANDR synthesises.
    let synthetic = crate::platform::drm::Mode {
        width: 800,
        height: 600,
        vrefresh: 60,
        ..Default::default()
    };
    assert!(mode_timing(&synthetic).is_none(), "clock_khz==0 => None");
}

#[test]
fn glx_vendor_names_are_nvidia_first_then_mesa_on_nvidia() {
    use ash::vk::DriverId;

    // libglvnd tries the names left to right and falls through when
    // one will not load, so "mesa" is insurance for the routine
    // package split where the NVIDIA Vulkan ICD is installed but
    // libGLX_nvidia.so is not. Without it libglvnd resolves no
    // vendor and lands on FALLBACK_VENDOR_NAME "indirect", which is
    // worse than today's llvmpipe.
    assert_eq!(
        glx_vendor_names_for_driver(DriverId::NVIDIA_PROPRIETARY),
        "nvidia mesa"
    );
}

#[test]
fn glx_vendor_names_stay_mesa_on_every_other_driver() {
    use ash::vk::DriverId;
    use yserver_protocol::x11::glx as x11glx;

    // The mapping is deliberately binary. Entries for other drivers
    // are omitted because nobody working on this repo can measure
    // them, and an unmeasured mapping that redirects a working
    // configuration onto a nonexistent libGLX_*.so is worse than
    // the status quo.
    for driver in [
        DriverId::MESA_LLVMPIPE,
        DriverId::INTEL_OPEN_SOURCE_MESA,
        DriverId::MESA_RADV,
        DriverId::AMD_PROPRIETARY,
    ] {
        assert_eq!(glx_vendor_names_for_driver(driver), x11glx::VENDOR_NAMES);
    }
}

/// Nothing else in this file calls `glx_vendor_names` through the
/// `Backend` trait — every other assertion here calls
/// `glx_vendor_names_for_driver` directly. Going through UFCS on
/// the trait forces dispatch through `impl Backend for
/// KmsBackend` rather than a same-named inherent method, and pins
/// the `platform.vk == None` fallback (`PlatformBackend::for_tests`
/// leaves `vk` unset — asserted at platform.rs:3312).
///
/// What this actually pins down is the fallback body: with `vk ==
/// None`, `glx_vendor_names` takes the `map_or` default branch and
/// returns `x11glx::VENDOR_NAMES` ("mesa") without ever calling
/// `glx_vendor_names_for_driver`. It fails if that `map_or` is
/// changed to `unwrap`/`expect` on `vk` (panics instead of falling
/// back) or if the no-Vulkan default is changed away from "mesa".
/// It does *not* discriminate trait dispatch from inherent-method
/// dispatch — with `vk == None` the two paths return the identical
/// `&'static str`, so this assertion would pass either way; the
/// UFCS call is here for documentation of intent, not as a check
/// on how the method is dispatched.
#[test]
fn glx_vendor_names_falls_back_to_mesa_with_no_vk() {
    use yserver_protocol::x11::glx as x11glx;

    assert_eq!(
        Backend::glx_vendor_names(&KmsBackend::for_tests()),
        x11glx::VENDOR_NAMES
    );
}

/// A big-endian client's XkbUseExtension through the real KMS backend
/// gets Xvfb's big-endian "unsupported" answer (supported=False,
/// sequence and server version 1.0 in big-endian:
/// `01000002 00000000 00010000 00…`) — yserver's XKB is
/// little-endian only, and Xorg's way to refuse a client is
/// supported=False. The backend's own reply is little-endian.
#[test]
fn xkb_use_extension_from_a_big_endian_client_is_refused_in_its_byte_order() {
    use std::{
        collections::{HashMap, HashSet, VecDeque},
        io::Read,
        os::unix::net::UnixStream,
        sync::{Arc, Mutex, atomic::AtomicU16},
    };
    use yserver_core::{core_loop::process_request, server::ClientState};
    use yserver_protocol::x11::{ClientByteOrder, ClientId, RequestHeader, SequenceNumber};

    let mut backend = KmsBackend::for_tests();
    let mut state = ServerState::new();
    let (mut peer, writer) = UnixStream::pair().unwrap();
    writer.set_nonblocking(true).unwrap();
    state.clients.insert(
        7,
        ClientState {
            writer: Arc::new(Mutex::new(yserver_core::transport::Transport::Unix(writer))),
            byte_order: ClientByteOrder::BigEndian,
            last_sequence: Arc::new(AtomicU16::new(0)),
            resource_id_base: 0,
            resource_id_mask: 0,
            event_masks: HashMap::new(),
            save_set: HashSet::new(),
            big_requests_enabled: false,
            xi2_masks: HashMap::new(),
            xi1_event_classes: HashSet::new(),
            xi1_window_event_classes: HashMap::new(),
            outbound: VecDeque::new(),
            watching_writable: false,
            write_failed: false,
            focused_window: yserver_core::resources::ROOT_WINDOW,
            reader_control: None,
            is_local: true,
            fd_passing: true,
        },
    );
    let xkb_major = backend.xkb_opcode().expect("KMS advertises XKB");
    process_request::process_request(
        &mut state,
        &mut backend as &mut dyn Backend,
        ClientId(7),
        SequenceNumber(2),
        RequestHeader {
            opcode: xkb_major,
            data: 0,
            length_units: 2,
        },
        // wantedMajor=1, wantedMinor=0 as a big-endian client sends it.
        &[0, 1, 0, 0],
        None,
    )
    .expect("XkbUseExtension");
    let mut reply = [0u8; 32];
    peer.read_exact(&mut reply).unwrap();
    let mut expected = [0u8; 32];
    expected[..10].copy_from_slice(&[1, 0, 0, 2, 0, 0, 0, 0, 0, 1]);
    assert_eq!(reply, expected);
}

/// Routing regression guard: minor 13 is GetIndicatorMap (clients send
/// it 8×), minor 22 is ListComponents. FU4 wired the 416-byte
/// IndicatorMap reply to 22 by mistake and stubbed the real opcode 13.
/// xkb_proxy(13) must return the 416-byte IndicatorMap; xkb_proxy(22)
/// must NOT (an IndicatorMap-shaped reply at 22 is wrong).
#[test]
fn xkb_proxy_routes_indicator_map_to_minor_13() {
    let mut backend = KmsBackend::for_tests();
    let mut intern = |_name: &str| 1u32;

    let r13 = backend
        .xkb_proxy(None, 13, &[], &mut intern)
        .expect("xkb_proxy ok")
        .expect("minor 13 returns a reply");
    assert_eq!(
        r13.len(),
        416,
        "minor 13 (GetIndicatorMap) must be the 32 + 32*12 IndicatorMap reply"
    );

    let r22 = backend
        .xkb_proxy(None, 22, &[], &mut intern)
        .expect("xkb_proxy ok");
    // minor 22 (ListComponents) must not emit an IndicatorMap-shaped reply.
    assert_ne!(
        r22.as_ref().map(Vec::len),
        Some(416),
        "minor 22 (ListComponents) must not be the IndicatorMap reply"
    );
}

#[test]
fn xkb_proxy_get_map_respects_client_requested_parts() {
    let mut backend = KmsBackend::for_tests();
    let mut intern = |_name: &str| 1u32;
    let mut body = [0u8; 20];
    body[0..2].copy_from_slice(&0x0100_u16.to_le_bytes()); // UseCoreKbd
    body[2..4].copy_from_slice(&0x0003_u16.to_le_bytes()); // KeyTypes|KeySyms

    let reply = backend
        .xkb_proxy(None, 8, &body, &mut intern)
        .expect("xkb_proxy ok")
        .expect("minor 8 returns a GetMap reply");

    assert_eq!(
        u16::from_le_bytes([reply[12], reply[13]]),
        0x0003,
        "GetMap present must be limited to the requested KeyTypes|KeySyms"
    );
    assert_eq!(u16::from_le_bytes([reply[22], reply[23]]), 0);
    assert_eq!(reply[24], 0, "unrequested KeyActions must be absent");
    assert_eq!(reply[33], 0, "unrequested ModifierMap must be absent");
    assert_eq!(
        u16::from_le_bytes([reply[38], reply[39]]),
        0,
        "unrequested VirtualMods must be absent"
    );
}

#[test]
fn backend_set_keymap_rmlvo_reports_range() {
    let mut backend = KmsBackend::for_tests();
    let range = backend.set_keymap_rmlvo("evdev", "pc105", "de", "", None);
    // Assert the robust half concretely and the xkb-data-derived half
    // structurally: max is a hard clamp to 255; min is the evdev floor
    // (8 offset) and is 9 on current xkb-data, but assert a plausible
    // range so a future xkb-data shift doesn't read as a logic break.
    let (min, max) = range.expect("de map compiles");
    assert_eq!(max, 255, "evdev keycode ceiling is clamped to 255");
    assert!(
        (8..=9).contains(&min),
        "evdev min keycode (8 offset), got {min}"
    );
    // Re-applying the same RMLVO is a no-op (None = no change).
    let again = backend.set_keymap_rmlvo("evdev", "pc105", "de", "", None);
    assert_eq!(again, None);
}

mod get_image_planes {
    use super::super::{
        apply_gc_function, apply_z_plane_mask, copy_area_clip_gpu_eligible, depth_plane_mask,
        read_z_pixmap_pixel, write_z_pixmap_pixel, z_to_xy_planes,
    };
    use yserver_core::backend::GcFunction;

    #[test]
    fn depth_plane_mask_truncates_to_depth() {
        assert_eq!(depth_plane_mask(1), 0x1);
        assert_eq!(depth_plane_mask(4), 0x0f);
        assert_eq!(depth_plane_mask(8), 0xff);
        assert_eq!(depth_plane_mask(24), 0x00ff_ffff);
        assert_eq!(depth_plane_mask(32), u32::MAX);
    }

    // Regression guard for the gkrellm/compositor fix (2026-06-20): a
    // clip-masked CopyArea only takes the fast GPU per-run blit for plain
    // GXcopy with a full plane-mask; everything else must fall back to the
    // CPU read-modify-write path. Routing GXcopy+full-mask to the GPU is
    // what removed gkrellm's per-run readback stall.
    #[test]
    fn copy_area_clip_gpu_eligible_only_for_gxcopy_full_mask() {
        use yserver_core::backend::GcFunction;
        let full = depth_plane_mask(24);
        // GXcopy + full plane-mask → GPU fast path (gkrellm's case).
        assert!(copy_area_clip_gpu_eligible(GcFunction::Copy, full, full));
        // Non-Copy rop → CPU read-modify-write path required.
        assert!(!copy_area_clip_gpu_eligible(GcFunction::Xor, full, full));
        assert!(!copy_area_clip_gpu_eligible(GcFunction::Invert, full, full));
        // Partial plane-mask → CPU path even for GXcopy.
        assert!(!copy_area_clip_gpu_eligible(
            GcFunction::Copy,
            full & !1,
            full
        ));
    }

    #[test]
    fn z_mask_depth24_zeroes_unrequested_planes() {
        // One BGRA pixel 0x00ff_80ff (LE bytes B=0xff G=0x80 R=0xff X=0).
        let mut px = vec![0xff, 0x80, 0xff, 0x00];
        apply_z_plane_mask(&mut px, 24, 0x0000_00ff); // blue planes only
        assert_eq!(px, vec![0xff, 0x00, 0x00, 0x00]);
    }

    #[test]
    fn z_mask_depth8_masks_bytes() {
        let mut bytes = vec![0xab, 0x0f, 0xf0, 0x00];
        apply_z_plane_mask(&mut bytes, 8, 0x0f);
        assert_eq!(bytes, vec![0x0b, 0x0f, 0x00, 0x00]);
    }

    #[test]
    fn z_mask_depth4_masks_bytes() {
        // Depth-4 wire ZPixmap is nibble-PACKED (two pixels per
        // byte, low nibble first — see pack_from_storage), so the
        // mask applies to BOTH nibbles independently. The original
        // expectation here predated the a2d5480 nibble packing and
        // assumed one pixel per byte.
        // Full mask is the identity.
        let mut bytes = vec![0xab, 0x0f, 0xf0, 0x00];
        apply_z_plane_mask(&mut bytes, 4, 0x0f);
        assert_eq!(bytes, vec![0xab, 0x0f, 0xf0, 0x00]);
        // Partial mask 0b0011 keeps the low two planes of each pixel.
        let mut bytes = vec![0xab, 0x0f, 0xf0, 0x00];
        apply_z_plane_mask(&mut bytes, 4, 0x03);
        assert_eq!(bytes, vec![0x23, 0x03, 0x30, 0x00]);
    }

    #[test]
    fn xy_planes_depth4_unpacks_nibbles() {
        // pixel0=1, pixel1=2 packed low-nibble first into 0x21.
        let z = [0x21, 0x00, 0x00, 0x00];
        let out = z_to_xy_planes(&z, 2, 1, 4, 0x3);
        assert_eq!(out.len(), 2 * 4);
        // Plane 1 first: pixel1 only.
        assert_eq!(out[0], 0b0000_0010);
        // Plane 0 second: pixel0 only.
        assert_eq!(out[4], 0b0000_0001);
    }

    #[test]
    fn z_mask_depth1_empty_mask_zeroes() {
        let mut bytes = vec![0xff, 0xff, 0xff, 0xff];
        apply_z_plane_mask(&mut bytes, 1, 0);
        assert_eq!(bytes, vec![0, 0, 0, 0]);
    }

    #[test]
    fn xy_planes_msb_first_lsb_bit_order() {
        // 2x1 depth-24 image: pixel0 = 0x000001 (bit 0 set),
        // pixel1 = 0x800000 (bit 23 set). Request planes 23 and 0.
        let z = [
            0x01, 0x00, 0x00, 0x00, // pixel (0,0) BGRA LE
            0x00, 0x00, 0x80, 0x00, // pixel (1,0)
        ];
        let mask = (1 << 23) | 1;
        let out = z_to_xy_planes(&z, 2, 1, 24, mask);
        // Two planes, scanline pad 32 bits → 4 bytes per row.
        assert_eq!(out.len(), 2 * 4);
        // Plane 23 first (most significant): pixel1 → bit 1 LSBFirst.
        assert_eq!(out[0], 0b0000_0010);
        // Plane 0 second: pixel0 → bit 0.
        assert_eq!(out[4], 0b0000_0001);
    }

    #[test]
    fn xy_planes_depth1_is_identity_for_plane0() {
        // 40x2 depth-1 bitmap: stride = ceil(40/32)*4 = 8 bytes.
        let mut z = vec![0u8; 16];
        z[0] = 0xa5;
        z[9] = 0x3c;
        let out = z_to_xy_planes(&z, 40, 2, 1, 0x1);
        assert_eq!(out, z);
    }

    #[test]
    fn xy_planes_empty_mask_is_empty() {
        let z = [0u8; 16];
        assert!(z_to_xy_planes(&z, 2, 2, 24, 0).is_empty());
    }

    #[test]
    fn depth4_z_pixmap_pixel_round_trip_uses_nibbles() {
        let mut z = vec![0u8; 4];
        write_z_pixmap_pixel(&mut z, 4, 2, 0, 0, 0x1);
        write_z_pixmap_pixel(&mut z, 4, 2, 1, 0, 0xe);
        assert_eq!(z[0], 0xe1);
        assert_eq!(read_z_pixmap_pixel(&z, 4, 2, 0, 0), 0x1);
        assert_eq!(read_z_pixmap_pixel(&z, 4, 2, 1, 0), 0xe);
    }

    #[test]
    fn gc_function_respects_plane_mask() {
        assert_eq!(
            apply_gc_function(GcFunction::Copy, 0b1111, 0b0000, 0b0101),
            0b0101
        );
        assert_eq!(
            apply_gc_function(GcFunction::Invert, 0, 0b0011, 0b0001),
            0b0010
        );
        assert_eq!(
            apply_gc_function(GcFunction::Nor, 0b0001, 0b0010, 0b1111),
            0b1100
        );
    }
}

/// Stage 1b acceptance gate (synthetic): v2 constructs through
/// `for_tests` and answers the capability accessors with the
/// same values as v1. This is the "boots far enough to service
/// capability queries" check from the spec.
#[test]
fn skeleton_advertises_expected_capabilities() {
    let b = KmsBackend::for_tests();
    assert_eq!(b.window_id(), 1);
    assert_eq!(b.root_visual_xid(), 0x21);
    assert_eq!(b.render_opcode(), Some(133));
    assert_eq!(b.xkb_opcode(), Some(136));
    assert_eq!(b.xkb_info(), Some((136, 85, 162)));
    assert_eq!(b.composite_opcode(), Some(144));
    // Non-trivial format passes through untouched; 0 returns None.
    assert_eq!(b.render_format_for_ynest_id(0), None);
    assert_eq!(b.render_format_for_ynest_id(0x12345), Some(0x12345));
    // KMS has no upstream host visuals, but it still advertises
    // server-local ARGB ids so CreateWindow can preserve depth 32.
    assert_eq!(b.argb_visual_xid(), Some(0x103));
    assert_eq!(b.argb_colormap_xid(), Some(0x104));
}

