    let connector = layout.key.connector_name.clone();
    let mode = yserver_core::backend::ModeSpec {
        width: layout.width,
        height: layout.height,
        vrefresh: layout.output.picked.vrefresh,
    };
    let (x, y) = (layout.x, layout.y);
