fn rect(x: i16, y: i16, width: u16, height: u16) -> Rectangle16 {
    Rectangle16 {
        x,
        y,
        width,
        height,
    }
}

fn as_set(v: Vec<Rectangle16>) -> std::collections::BTreeSet<(i16, i16, u16, u16)> {
    v.into_iter()
        .map(|r| (r.x, r.y, r.width, r.height))
        .collect()
}

